from __future__ import annotations


def training_page_html() -> str:
    return r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MetaTrader AI Training Lab</title>
<style>
:root{color-scheme:dark;--bg:#111827;--card:#1f2937;--card2:#0f172a;--border:#374151;--text:#e5e7eb;--muted:#94a3b8;--blue:#2563eb;--green:#10b981;--amber:#f59e0b;--red:#fb7185}
*{box-sizing:border-box}body{font-family:system-ui,-apple-system,sans-serif;background:var(--bg);color:var(--text);margin:0;padding:24px}.wrap{max-width:1180px;margin:auto}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}.top h1{margin:0 0 6px}.nav a{display:inline-block;color:#bfdbfe;text-decoration:none;border:1px solid var(--border);border-radius:10px;padding:9px 12px}.card{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:20px;margin:16px 0}.muted{color:var(--muted)}.ok{color:#4ade80}.warn{color:#fbbf24}.bad{color:var(--red)}.formgrid{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:12px}.field label{display:block;color:var(--muted);font-size:13px;margin:0 0 6px}.field input,.field select{width:100%;background:var(--card2);color:#fff;border:1px solid #475569;border-radius:9px;padding:10px;min-height:42px}.pipeline{display:grid;grid-template-columns:1fr auto 1fr auto 1fr;gap:10px;align-items:center;margin-top:14px}.stage{background:var(--card2);border:1px solid var(--border);border-radius:12px;padding:14px}.stage b{display:block;font-size:18px;margin-bottom:4px}.arrow{color:#64748b;font-size:24px}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:16px}button{background:var(--blue);color:#fff;border:0;border-radius:10px;padding:11px 17px;font-weight:750;cursor:pointer;min-height:42px}button.secondary{background:#334155}button.promote{background:#0f766e}button:disabled{opacity:.45;cursor:not-allowed}.banner{border-radius:12px;padding:14px 16px;margin:14px 0;border:1px solid var(--border);background:var(--card2)}.banner.good{border-color:#166534}.banner.caution{border-color:#92400e}.metrics{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:10px}.metric{background:var(--card2);border:1px solid var(--border);border-radius:12px;padding:12px}.metric span{color:var(--muted);font-size:12px}.metric b{font-size:21px;display:block;margin:4px 0}.splitgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.split h3{margin-top:0}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:8px}.comparison div{background:#111827;border-radius:8px;padding:8px}.comparison small{color:var(--muted);display:block}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:760px}th,td{padding:9px;border-bottom:1px solid var(--border);text-align:left;font-size:13px}th{color:var(--muted)}code{color:#93c5fd}.hidden{display:none}.progress{height:8px;background:#0f172a;border-radius:99px;overflow:hidden;margin:12px 0}.progress i{display:block;width:0;height:100%;background:#3b82f6;transition:width .4s}.note{font-size:13px;color:var(--muted);line-height:1.5}@media(max-width:900px){.formgrid,.metrics{grid-template-columns:1fr 1fr}.splitgrid{grid-template-columns:1fr}.pipeline{grid-template-columns:1fr}.arrow{transform:rotate(90deg);text-align:center}}@media(max-width:560px){body{padding:12px}.formgrid,.metrics{grid-template-columns:1fr}.comparison{grid-template-columns:1fr}}
</style>
</head>
<body><div class="wrap">
<div class="top"><div><h1>MetaTrader AI — Training Lab</h1><div class="muted">Walk-forward threshold training for XAUUSD M15. Stable rollback reference: <code>57f4e157314611dd555eb8664caa78847d43d7d3</code></div></div><div class="nav"><a href="/control">← Bridge Control</a></div></div>

<div class="card">
<h2>1. Training dataset</h2>
<p id="historyStatus" class="muted">Reading synced MT5 history…</p>
<div class="formgrid">
<div class="field"><label for="startDate">Start date</label><input id="startDate" type="date"></div>
<div class="field"><label for="endDate">End date</label><input id="endDate" type="date"></div>
<div class="field"><label for="baseProfile">Starting profile</label><select id="baseProfile"><option value="MODEL_BASELINE">Stable calibrated baseline</option><option value="CURRENT">Current live sliders</option></select></div>
<div class="field"><label for="iterations">Candidate profiles</label><input id="iterations" type="number" min="8" max="80" step="1" value="24"></div>
<div class="field"><label for="balance">Starting balance $</label><input id="balance" type="number" min="10" step="10" value="1000"></div>
<div class="field"><label for="risk">Risk / trade %</label><input id="risk" type="number" min="0.05" max="5" step="0.05" value="0.5"></div>
<div class="field"><label for="rr">Reward : Risk</label><input id="rr" type="number" min="0.5" max="10" step="0.1" value="2"></div>
<div class="field"><label for="target">Tracking target $ / day</label><input id="target" type="number" min="0" step="1" value="10"></div>
</div>
<p class="note">Risk and R:R are held fixed during optimization. The trainer changes signal thresholds only; it cannot reach the $10/day target by silently increasing risk.</p>
</div>

<div class="card">
<h2>2. Walk-forward training process</h2>
<div class="pipeline"><div class="stage"><b>TRAIN · 60%</b><span class="muted">Search candidate thresholds on the oldest data.</span></div><div class="arrow">→</div><div class="stage"><b>VALIDATE · 20%</b><span class="muted">Choose among the strongest training candidates.</span></div><div class="arrow">→</div><div class="stage"><b>HOLDOUT · 20%</b><span class="muted">Final unseen check. Never used to tune the candidate.</span></div></div>
<div class="actions"><button id="trainBtn" disabled>Train candidate model</button><span id="trainMsg" class="muted"></span></div><div class="progress"><i id="progressBar"></i></div>
<p class="note">This is parameter training/optimization for our six-factor decision engine, not neural-network training. Historical optimization can overfit, so a candidate can only be promoted to DEMO when it also beats the baseline on the untouched holdout segment.</p>
</div>

<div id="results" class="hidden">
<div class="card"><h2>3. Training verdict</h2><div id="verdict" class="banner"></div><div class="metrics" id="headlineMetrics"></div><div class="actions"><button id="promoteBtn" class="promote" disabled>Apply candidate to live DEMO thresholds</button><span id="promoteMsg" class="muted"></span></div></div>

<div class="card"><h2>4. Baseline vs candidate</h2><div class="splitgrid" id="splitCards"></div></div>

<div class="card"><h2>5. Threshold changes</h2><div class="tablewrap"><table><thead><tr><th>Parameter</th><th>Baseline</th><th>Candidate</th><th>Change</th></tr></thead><tbody id="thresholdRows"></tbody></table></div></div>

<div class="card"><h2>6. Finalists</h2><p class="muted">Top candidates after training, ranked through the validation stage. Holdout is opened only for the selected winner.</p><div class="tablewrap"><table><thead><tr><th>#</th><th>Train E</th><th>Train DD</th><th>Validation E</th><th>Validation DD</th><th>Validation trades</th></tr></thead><tbody id="finalistRows"></tbody></table></div></div>
</div>
</div>
<script>
let historyDates=[];let lastCandidate=null;
const $=id=>document.getElementById(id);
function money(v){const n=Number(v)||0;return `${n<0?'-$':'$'}${Math.abs(n).toFixed(2)}`}
function signed(v,d=2){const n=Number(v)||0;return `${n>0?'+':''}${n.toFixed(d)}`}
async function loadHistory(){try{const r=await fetch('/history/status?symbol=XAUUSD_o&timeframe=M15');const h=await r.json();if(!r.ok||!h.bars)throw new Error('No synced history yet.');historyDates=(h.available_dates||[]).slice().sort();$('historyStatus').textContent=`Synced ${h.bars} M15 bars · ${h.earliest_date} → ${h.latest_date} · ${historyDates.length} trading dates`;$('historyStatus').className='ok';for(const id of ['startDate','endDate']){$(id).min=h.earliest_date;$(id).max=h.latest_date;}if(historyDates.length){$('startDate').value=historyDates[0];$('endDate').value=historyDates[historyDates.length-1];$('trainBtn').disabled=historyDates.length<15;}if(historyDates.length<15){$('trainMsg').textContent='Need at least 15 synced trading days.';$('trainMsg').className='warn';}}catch(e){$('historyStatus').textContent=e.message;$('historyStatus').className='bad';}}
function metricHtml(label,value,sub=''){return `<div class="metric"><span>${label}</span><b>${value}</b><small class="muted">${sub}</small></div>`}
function splitCard(name,candidate,baseline,range){const deltaE=candidate.expectancy_r-baseline.expectancy_r,deltaDD=candidate.max_drawdown_r-baseline.max_drawdown_r;return `<div class="stage split"><h3>${name}</h3><div class="muted" style="margin-bottom:8px">${range[0]} → ${range[1]}</div><div class="comparison"><div><small>Candidate expectancy</small><b>${candidate.expectancy_r.toFixed(2)}R</b></div><div><small>Baseline expectancy</small><b>${baseline.expectancy_r.toFixed(2)}R</b></div><div><small>Candidate avg/day</small><b>${money(candidate.avg_daily_pnl)}</b></div><div><small>Baseline avg/day</small><b>${money(baseline.avg_daily_pnl)}</b></div><div><small>Δ expectancy</small><b class="${deltaE>=0?'ok':'bad'}">${signed(deltaE)}R</b></div><div><small>Δ drawdown</small><b class="${deltaDD<=0?'ok':'bad'}">${signed(deltaDD)}R</b></div></div><p class="note">${candidate.trades} trades · ${candidate.win_rate.toFixed(1)}% WR · ${candidate.profitable_days_percent.toFixed(1)}% profitable days · DD ${candidate.max_drawdown_r.toFixed(2)}R</p></div>`}
function render(data){lastCandidate=data.candidate.config;$('results').classList.remove('hidden');const good=data.status==='PROMISING';$('verdict').className='banner '+(good?'good':'caution');$('verdict').innerHTML=`<b>${good?'PROMISING CANDIDATE':'KEEP STABLE BASELINE'}</b><div style="margin-top:5px">${data.promotion_reason}</div><div class="muted" style="margin-top:5px">${data.warning}</div>`;const h=data.candidate.holdout,bh=data.baseline.holdout,gap=data.candidate.holdout_avg_daily_gap_to_target;$('headlineMetrics').innerHTML=metricHtml('Holdout expectancy',`${h.expectancy_r.toFixed(2)}R/trade`,`baseline ${bh.expectancy_r.toFixed(2)}R`)+metricHtml('Holdout avg / day',money(h.avg_daily_pnl),`target ${money(data.target_daily_pnl)} · gap ${money(gap)}`)+metricHtml('Holdout drawdown',`${h.max_drawdown_r.toFixed(2)}R`,`baseline ${bh.max_drawdown_r.toFixed(2)}R`)+metricHtml('Candidates evaluated',data.candidates_evaluated,`${data.split.train_days}/${data.split.validation_days}/${data.split.holdout_days} day split`);$('splitCards').innerHTML=splitCard('TRAIN',data.candidate.train,data.baseline.train,data.split.train)+splitCard('VALIDATION',data.candidate.validation,data.baseline.validation,data.split.validation)+splitCard('HOLDOUT',data.candidate.holdout,data.baseline.holdout,data.split.holdout);const b=data.baseline.config,c=data.candidate.summary;const labels={dynamic_levels:'Dynamic levels',static_levels:'Static / OrderBlock',fibonacci:'Fibonacci',patterns:'Patterns / Harmonic',pivots:'Pivots',divergence:'Divergence / Momentum',min_pass_count:'Minimum passed factors',min_total_score:'Minimum total score',min_side_edge:'Minimum BUY/SELL edge'};$('thresholdRows').innerHTML=Object.keys(labels).map(k=>{const d=Number(c[k])-Number(b[k]);return `<tr><td>${labels[k]}</td><td>${b[k]}</td><td>${c[k]}</td><td class="${d===0?'muted':d>0?'warn':'ok'}">${d>0?'+':''}${d}</td></tr>`}).join('');$('finalistRows').innerHTML=data.top_candidates.map((x,i)=>`<tr><td>${i+1}</td><td>${x.train.expectancy_r.toFixed(2)}R</td><td>${x.train.max_drawdown_r.toFixed(2)}R</td><td>${x.validation.expectancy_r.toFixed(2)}R</td><td>${x.validation.max_drawdown_r.toFixed(2)}R</td><td>${x.validation.trades}</td></tr>`).join('');$('promoteBtn').disabled=!data.promotion_allowed;$('promoteMsg').textContent=data.promotion_allowed?'Eligible for DEMO promotion; forward testing is still required.':'Promotion disabled because holdout gates were not passed.';$('promoteMsg').className=data.promotion_allowed?'ok':'warn';}
async function train(){const start=$('startDate').value,end=$('endDate').value;if(!start||!end||start>end){$('trainMsg').textContent='Check the date range.';$('trainMsg').className='bad';return;}const selected=historyDates.filter(d=>d>=start&&d<=end);if(selected.length<15){$('trainMsg').textContent='Choose at least 15 synced trading days.';$('trainMsg').className='bad';return;}const body={symbol:'XAUUSD_o',timeframe:'M15',start_date:start,end_date:end,starting_balance:Number($('balance').value),risk_percent:Number($('risk').value),reward_risk_ratio:Number($('rr').value),iterations:Number($('iterations').value),base_profile:$('baseProfile').value,target_daily_pnl:Number($('target').value)};$('trainBtn').disabled=true;$('promoteBtn').disabled=true;$('results').classList.add('hidden');$('trainMsg').textContent=`Training ${body.iterations} candidates across ${selected.length} trading days…`;$('trainMsg').className='muted';$('progressBar').style.width='55%';try{const r=await fetch('/training/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Training failed');$('progressBar').style.width='100%';$('trainMsg').textContent=`Done · ${data.candidates_evaluated} candidates evaluated`;$('trainMsg').className='ok';render(data);}catch(e){$('progressBar').style.width='0';$('trainMsg').textContent=e.message;$('trainMsg').className='bad';}finally{$('trainBtn').disabled=false;}}
async function promote(){if(!lastCandidate)return;$('promoteBtn').disabled=true;$('promoteMsg').textContent='Applying to live DEMO thresholds…';try{const r=await fetch('/strategy/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(lastCandidate)});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Apply failed');$('promoteMsg').textContent='Candidate applied. Keep it on DEMO and collect forward results before any further promotion.';$('promoteMsg').className='ok';}catch(e){$('promoteMsg').textContent=e.message;$('promoteMsg').className='bad';$('promoteBtn').disabled=false;}}
$('trainBtn').addEventListener('click',train);$('promoteBtn').addEventListener('click',promote);loadHistory();
</script></body></html>'''
